import { GetTimeStringBySeconds } from "@/time/library.ts";

// 榜单时间条（t-slider）的展示辅助。
//
// 时间条的 tooltip 文案由 t-slider 的 label 函数提供，而各版本 tdesign 传给这个函数的
// 参数并不一致：1.17 及以前会调用 renderTNodeJSX 并把 { value } 传进来；1.20 起改成把
// label 函数直接当作 tooltip 内容渲染，调用时只给一个空对象。按老签名解构 params.value
// 会拿到 undefined，格式化结果是空串，配合 tooltip 的 hideEmptyPopup 就会让时间条
// 悬停/拖动时完全不显示 tooltip。抽成纯函数便于单测固定「拿不到值时的兜底口径」。

/** 滑块 value 的形态：单值滑块是 number，range 滑块是 number[] */
type SliderLabelValue = number | number[];

/**
 * 生成时间条 tooltip 文案。
 *
 * @param params tdesign 传给 label 函数的参数，可能缺 value（1.20 起传空对象）
 * @param currentSeconds 当前进度秒数，拿不到 params.value 时的兜底值
 */
export function formatRankTimeBarLabel(params: { value?: SliderLabelValue } | undefined, currentSeconds: number): string {
  const rawValue = params?.value;
  // range 滑块的数组值不适用于本页（单值进度条），同样按兜底处理
  const seconds = typeof rawValue === "number" ? rawValue : currentSeconds;
  return GetTimeStringBySeconds(seconds);
}
